// What Framework - Import changes
//
// Every name the root entry (`what-framework`, and `what-core` alike) stopped
// exporting in 0.15.0, and where it went, the names it exports with React's
// meaning instead of What's, then the internal interfaces new in 0.15 that the
// root entry never exported. This table is the one list: the docs
// (docs/UPGRADING.md, generated by scripts/generate-import-changes.mjs),
// what-compiler's Vite plugin, eslint-plugin-what's no-moved-imports rule,
// validateImports() and tools reading what-core/internal all take it from
// here, so agents and people see the same answer.
//
// A record is { name, to, as?, note, answer, onRoot?, neverOnRoot? }:
//   name         the name as it is imported
//   to           the module that exports it now, or null when it is gone
//   as           its new name, when it was renamed
//   note         why, ending with what to write instead
//   answer       what an import of the name from the root entry is told: the
//                note, then the import to write (built from the fields above)
//   onRoot       true for a name the root entry exports again, with React's
//                meaning: the record says where What's export of that name
//                went, and only an import of its new name (`as`) from the root
//                entry is answered
//   neverOnRoot  true for an internal interface new in 0.15 that the root
//                entry never exported, listed so an import of it is answered
// A what-framework/<kit> path has a what-core/<kit> twin with the same exports.
// A row with `names` stands for one record per name.

export const IMPORT_CHANGES = /* @__PURE__ */ table([
  // Names that meant something else in React.
  { name: 'useTransition', to: 'what-framework/motion', as: 'useTween', onRoot: true, note: 'The animation helper formerly named useTransition is useTween. useTransition and startTransition on the root entry are React\'s transition API: const [isPending, start] = useTransition(), where isPending is an accessor, read as isPending().' },
  { name: 'transition', to: 'what-framework/motion', as: 'transitionClass', note: 'The enter/leave class helper is transitionClass(name, active).' },
  { name: 'on', to: 'what-framework/render', note: 'on(el, event, handler) is a fine-grained rendering primitive; in components write onClick={...} in JSX.' },

  // Deleted: duplicates of names that stay.
  { name: 'each', to: null, note: 'Render lists with .map() and a key prop, or <For>.' },
  { name: 'atom', to: null, note: 'Use signal(initial).' },
  { name: 'storeComputed', to: null, note: 'Use derived(fn) in the store definition.' },
  { name: 'onRootCleanup', to: null, note: 'Use onCleanup(fn): it attaches to the component being rendered, or else to the reactive owner (createRoot, a list row).' },
  { name: 'signalMemo', to: null, note: 'Use computed(fn), which recomputes only when read and skips readers when the value is unchanged.' },
  { name: 'getLoaderData', to: null, note: 'Use useLoaderData(), which reads the same payload on the client and the render context on the server.' },
  { name: '_template', to: null, note: 'Use template() from what-framework/render; compiled output imports _$template from there.' },
  { name: 'getResource', to: null, note: 'Use createResource(fetcher, { key }), which reads the hydrated value for its key.' },

  // One island component: the server's. What the compiler lowers client:*
  // directives to is a compiler target.
  { name: 'Island', to: 'what-framework/server', note: 'The island component is what-framework/server\'s Island({ name, props, mode }), which the client hydrates through the island registry (island(), hydrateIslands()). A JSX client:* directive (<Counter client:idle />) compiles to _$Island from what-framework/render, an island that hydrates itself; code written with h() calls that the same way: h(_$Island, { component: Counter, mode: \'idle\' }).' },

  // The error collector: the diagnostics channel replaced it.
  { name: 'collectError', to: null, note: 'Nothing collects errors by hand: the runtime reports its coded diagnostics on one channel (getDiagnostics(), subscribeDiagnostics()), and what-devtools records thrown errors (getErrors()). Both are development-only: a production build reports nothing.' },
  { name: 'getCollectedErrors', to: null, note: 'Use getDiagnostics({ since }) for the coded diagnostics (since is the seq the previous call returned, not a timestamp), or getErrors() from what-devtools for thrown errors; both are development-only.' },
  { name: 'clearCollectedErrors', to: null, note: 'Use clearDiagnostics().' },

  // The agent context (window.__WHAT_AGENT__): what-devtools and
  // what-devtools-mcp replaced it.
  { name: 'installAgentContext', to: null, note: 'Use installDevTools() from what-devtools, which what-devtools-mcp\'s Vite plugin calls in development: it exposes the app\'s state as window.__WHAT_DEVTOOLS__, which the what_* MCP tools read.' },
  { to: null, names: ['registerComponent', 'unregisterComponent'], note: 'Delete the call: with what-devtools installed, every component is registered as it mounts and dropped as it unmounts.' },
  { to: null, names: ['registerSignal', 'unregisterSignal'], note: 'Delete the call: with what-devtools installed, every signal is registered as it is created, and nothing has to unregister it.' },
  { name: 'getMountedComponents', to: null, note: 'Use getSnapshot().components from what-devtools (development only), or the what_components MCP tool.' },
  { name: 'getActiveSignals', to: null, note: 'Use getSnapshot().signals from what-devtools (development only), or the what_signals MCP tool.' },
  { name: 'getHealth', to: null, note: 'Use the what_diagnose MCP tool (diagnostic codes, errors, hot effects, unread signals), or getDiagnostics() for the coded diagnostics alone.' },

  // Domain kits on subpaths.
  { to: 'what-framework/a11y', names: [
    'useFocus', 'useFocusRestore', 'useFocusTrap', 'FocusTrap', 'announce', 'announceAssertive',
    'SkipLink', 'useAriaExpanded', 'useAriaSelected', 'useAriaChecked', 'useRovingTabIndex',
    'VisuallyHidden', 'LiveRegion', 'useIds', 'useDescribedBy', 'useLabelledBy', 'Keys', 'onKey', 'onKeys',
  ], note: 'Accessibility helpers live in what-framework/a11y.' },
  { to: 'what-framework/ui', names: [
    'Skeleton', 'SkeletonText', 'SkeletonAvatar', 'SkeletonCard', 'SkeletonTable', 'IslandSkeleton',
    'useSkeleton', 'Placeholder', 'LoadingDots', 'Spinner',
  ], note: 'Skeletons and loading placeholders live in what-framework/ui.' },
  { to: 'what-framework/motion', names: [
    'spring', 'tween', 'easings', 'useGesture', 'useAnimatedValue', 'createTransitionClasses', 'cssTransition',
  ], note: 'Animation lives in what-framework/motion.' },
  { to: 'what-framework/dom', names: [
    'scheduleRead', 'scheduleWrite', 'flushScheduler', 'measure', 'mutate', 'useScheduledEffect',
    'nextFrame', 'raf', 'onResize', 'onIntersect', 'smoothScrollTo',
  ], note: 'The DOM read/write scheduler lives in what-framework/dom.' },
  { to: 'what-framework/dom', names: [
    'cls', 'style', 'debounce', 'throttle', 'useMediaQuery', 'useLocalStorage', 'useClickOutside', 'clearHead',
  ], note: 'DOM utilities live in what-framework/dom.' },
  { to: 'what-framework/form', names: [
    'useForm', 'useField', 'rules', 'simpleResolver', 'zodResolver', 'yupResolver',
    'Input', 'Textarea', 'Select', 'Checkbox', 'Radio', 'ErrorMessage',
  ], note: 'Forms live in what-framework/form.' },
  { to: 'what-framework/data', names: [
    'useFetch', 'useSWR', 'useQuery', 'useInfiniteQuery', 'invalidateQueries', 'prefetchQuery',
    'setQueryData', 'getQueryData', 'clearCache',
  ], note: 'The query, SWR and fetch hooks live in what-framework/data.' },

  // Fine-grained rendering primitives: the compiler's runtime, for code
  // written without JSX.
  { to: 'what-framework/render', names: [
    'template', 'svgTemplate', 'insert', 'mapArray', 'spread', 'setProp', 'delegateEvents',
    'classList', 'isHydrating', '_$template', '_$createComponent',
  ], note: 'Fine-grained rendering primitives live in what-framework/render, beside the rest of the compiled-JSX runtime.' },
  { name: '_setTextInsertHook', to: 'what-core/render', note: 'Text engines register their insert hook through what-core/render.' },

  // The contract between what-core and its sibling packages and tools.
  { to: 'what-core/internal', names: [
    '__setDevToolsHooks', '__drainPreinstallBuffer', '__getCacheSnapshot', 'configureGuardrails', 'getGuardrailConfig',
    'validateImports', 'ERROR_CODES', 'createWhatError', 'classifyError',
  ], note: 'Devtools hooks, guardrails and the error catalogue are tool interfaces in what-core/internal.' },
  { name: 'checkComponentName', to: null, note: 'Removed: a function that reaches the runtime is already being called as a component, so its name cannot reveal the lowercase JSX tag (rendered as an unknown element) the check was meant to catch. Name components in PascalCase.' },
  { name: 'installSignalReadGuardrail', to: null, note: 'Nothing to install: in development every signal and computed reports ERR_MISSING_SIGNAL_READ when it is converted to a string or a number, with or without what-devtools.' },
  { to: 'what-core/internal', names: [
    'getServerContext', 'setServerContext', 'runWithServerContext', '__installServerContextStorage',
    'beginHeadCollection', 'endHeadCollection', '_isAriaAttr', '_beginComponentSSR', '_endComponentSSR',
    '_mapArrayToArray', '__readHydrationData', '__resetHydrationData',
  ], note: 'Server-rendering internals are what-server\'s interface in what-core/internal; apps use getResponse() and useLoaderData().' },

  // New in 0.15, never on the root entry.
  { to: 'what-core/internal', neverOnRoot: true, names: [
    '__depsOf', '__subsOf', '__currentEffect', '__ownerOf', '__ownerPath', 'reportDiagnostic', 'IMPORT_CHANGES',
  ], note: 'Devtools hooks, guardrails and the error catalogue are tool interfaces in what-core/internal.' },
  { to: 'what-core/internal', neverOnRoot: true, names: [
    '_escapeHtml', '_runInComponentSSR', '_assignOwnerPath', '_ownerCounter', '_currentOwnerPath', '_actionStateKey', '_actionKeySalt', '_currentRowPath', '_enterRow', '_installRowKeys', '_leaveRow', '_renderSalt', '_tracksRows', '__flushOutsideServerContext', '__outsideServerContext', '__markServerProcess',
    '_rowKeyDigest', '_engine', '_runComponentAsync', '_runComponentSync',
  ], note: 'Server-rendering internals are what-server\'s interface in what-core/internal; apps use getResponse() and useLoaderData().' },
  { to: 'what-core/internal', neverOnRoot: true, names: [
    '__invalidateFromDevtools', '_tagQueries', '_formStatus', '_formStatusContext', '_resetForm', '_formMember', '_devAction', '__DEV__', '_urgent', '_currentTransition', '_onCommit', '_pathLoaded',
    '_contextOf', '_provide', '_isServerProcess',
  ], note: 'The query cache\'s devtools and router hooks, the status <Form> provides and its reset, the engine hooks a navigation uses and the development flag are what-devtools\', what-router\'s and what-server\'s interface in what-core/internal; apps use what-framework/data, useFormStatus(), <Form> and useTransition().' },
  { name: 'isVNode', to: 'what-core/internal', neverOnRoot: true, note: 'Whether a value is a vnode, by the brand only what-core\'s producers (h(), the JSX runtime, the boundaries) give: for libraries that make or inspect elements, such as what-react. Apps make elements with h() or JSX.' },
  { name: '_mountPortal', to: 'what-core/internal', neverOnRoot: true, note: 'The client renderer a portal\'s vnode carries: what-react\'s createPortal attaches it, so its portal also renders where it reaches a native What tree. Apps use <Portal>.' },
]);

function table(rows) {
  const records = rows.flatMap(({ names, ...row }) => (names ? names.map((name) => ({ name, ...row })) : [row]));
  return Object.freeze(records.map((change) => Object.freeze({ ...change, answer: answerFor(change) })));
}

function answerFor({ name, to, as, note }) {
  return to ? `${note} Import it with: import { ${as || name} } from '${to}'.` : `It was removed in 0.15. ${note}`;
}
